"""Generate docs/compliance/requirements-matrix.md and risk-register.md from catalog.py, and
security-review.md from security_review.py, so the documents and the Compliance screen can never
disagree (spec 13, 23; HIMS-COMP, HIMS-SEC-011)."""

from pathlib import Path

from . import catalog, security_review

DOCS = Path(__file__).resolve().parents[3] / "docs" / "compliance"
MATRIX = DOCS / "requirements-matrix.md"
RISKS = DOCS / "risk-register.md"
REVIEW = DOCS / "security-review.md"
HEADER = (
    "<!-- Generated by `python manage.py compliance_docs` from "
    "backend/apps/compliance/catalog.py. Do not edit by hand. -->\n"
)
_NAMES = {"US": "United States", "IN": "India", "ALL": "Both countries"}
_STATUS = {
    catalog.NS: "Not started",
    catalog.IP: "In progress",
    catalog.DONE: "Implemented, not verified",
}


def _cell(text: str) -> str:
    return " ".join(text.split()).replace("|", "\\|")


def render_matrix() -> str:
    out = [
        HEADER,
        "# Regulatory requirements matrix (spec 13, 26.7)\n",
        "An engineering summary to organise the work, **not legal advice**. Qualified counsel must "
        "confirm what applies, the wording and the dates (spec 26.7). The status here is the "
        "**starting** status; the live status, owner and evidence are on the **Compliance** page. "
        '"Implemented" means the software supports it, not that the hospital is compliant.\n',
    ]
    for jurisdiction in ("US", "IN", "ALL"):
        out += [
            f"## {_NAMES[jurisdiction]}\n",
            "| Code | Law | Citation | Requirement | What the law asks | What HIMS does | "
            "Starting status |",
            "|---|---|---|---|---|---|---|",
        ]
        for (
            code,
            where,
            regulation,
            citation,
            title,
            summary,
            support,
            start,
        ) in catalog.REQUIREMENTS:
            if where == jurisdiction:
                cells = [code, regulation, citation, title, summary, support, _STATUS[start]]
                out.append("| " + " | ".join(_cell(cell) for cell in cells) + " |")
        out.append("")
    return "\n".join(out).rstrip() + "\n"


def render_risks() -> str:
    out = [
        HEADER,
        "# Risk register: starting entries (spec 23; HIPAA 164.308(a)(1))\n",
        "Score = likelihood x impact (each 1 to 5). The live register, with owners, treatment and "
        "review dates, is on the **Compliance** page. Explained in "
        "[threat-model.md](threat-model.md). These are engineering estimates for the hospital's "
        "own risk assessment.\n",
        "| Code | Risk | Area | Likelihood | Impact | Score | What reduces it |",
        "|---|---|---|---|---|---|---|",
    ]
    rows = sorted(catalog.RISKS, key=lambda risk: (-risk[4] * risk[5], risk[0]))
    for code, title, description, category, likelihood, impact, mitigation in rows:
        cells = [
            code,
            f"**{title}**: {description}",
            category,
            str(likelihood),
            str(impact),
            str(likelihood * impact),
            mitigation,
        ]
        out.append("| " + " | ".join(_cell(cell) for cell in cells) + " |")
    return "\n".join(out).rstrip() + "\n"


def _review_header() -> str:
    return HEADER.replace("catalog.py", "security_review.py")


def render_review() -> str:
    review = security_review
    out = [
        _review_header(),
        "# Security review of the threat model: Phase 1 (spec 13, 23; HIMS-SEC-011)\n",
        f"**Reviewed:** {review.REVIEWED_ON.isoformat()} · **Reviewer:** {review.REVIEWER}\n",
        f"**Scope:** {review.SCOPE}\n",
        f"**Method:** {review.METHOD}\n",
        "Threats and controls: [threat-model.md](threat-model.md). Live view: the **Compliance** "
        "page, **Security review** tab, and **Security status** in the admin console.\n",
        "## Findings\n",
        "| Code | Severity | Area | Finding | Fix | Status | Tests |",
        "|---|---|---|---|---|---|---|",
    ]
    for code, severity, area, finding, fix, status, tests in review.FINDINGS:
        evidence = "<br>".join(f"`{test.split('::')[1]}`" for test in tests) or "—"
        cells = [code, severity, area, finding, fix, status, evidence]
        out.append("| " + " | ".join(_cell(cell) for cell in cells) + " |")
    out += [
        "",
        "## Checked and found sound\n",
        "| Area | What was checked |",
        "|---|---|",
    ]
    out += [f"| {_cell(area)} | {_cell(result)} |" for area, result in review.CHECKED]
    out += [
        "",
        "## The ten security tests of spec 13.5\n",
        "| # | Case | Status | How | Tests |",
        "|---|---|---|---|---|",
    ]
    for number, (case, status, how, tests) in enumerate(review.SPEC_CASES, start=1):
        evidence = "<br>".join(f"`{test}`" for test in tests) or "—"
        cells = [str(number), case, review.CASE_STATUS[status], how, evidence]
        out.append("| " + " | ".join(_cell(cell) for cell in cells) + " |")
    out += [
        "",
        "## Before real patient data\n",
        "This review does not replace these; they are in the hosting stage of the "
        "[roadmap](../status/roadmap.md).\n",
        "| Ticket | What |",
        "|---|---|",
    ]
    out += [f"| {ticket} | {_cell(what)} |" for ticket, what in review.BEFORE_GO_LIVE]
    return "\n".join(out).rstrip() + "\n"


def outputs() -> dict[Path, str]:
    return {MATRIX: render_matrix(), RISKS: render_risks(), REVIEW: render_review()}
